const db = require('better-sqlite3')('/workspace/world.db');

// Look up the product
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").get();
if (product) {
  console.log('=== PRODUCT ===');
  console.log('Name:', product.name);
  console.log('Category:', product.category);
  console.log('Description:', product.description);
  console.log('Compatible with:', product.compatible_with_json);
  console.log('Specs:', product.specs_json);
} else {
  console.log('Product PROD-2028EE not found');
}

